import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import {useHref} from 'react-router'

import Popup from '../../../../../common/Popup/Popup.lazy'
import {PointType} from '../../../BuildLog.types'
import {getFullBuildLogLinkParams} from '../../../BuildLog.utils'

import type {Props} from './TimelinePoint.types'

import styles from './TimelinePoint.module.css'

const popupDirections = [Directions.RIGHT_TOP, Directions.LEFT_TOP]
export default function TimelinePoint({
  buildId,
  buildAnchor,
  name,
  type,
  logTarget,
  style,
  onMouseEnter,
  onMouseLeave,
  onClick,
}: Props) {
  const href = useHref({
    search: objectToQuery(
      getFullBuildLogLinkParams({
        buildId,
        line: buildAnchor,
        expandState: [buildAnchor],
        target: logTarget,
        expandAll: false,
      }),
    ),
  })
  // const onClick = useLinkClickHandler(to)
  const anchor = (
    <IconButton
      href={href}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      onClick={onClick}
      className={styles.pointButton}
      iconClassName={styles.pointIcon}
      icon="exception"
    />
  )
  return (
    <Dropdown
      className={styles.wrapper}
      style={style}
      anchor={anchor}
      hoverMode
      clickMode={false}
      hoverHideTimeOut={0}
      hoverShowTimeOut={0}
    >
      <Popup directions={popupDirections} top={-8} className={styles.popup} trapFocus={false}>
        <div
          className={classNames(styles.popupContent, {
            [styles.failure]: type === PointType.FAILURE,
          })}
        >
          {name ??
            `${type === 'FAILURE' ? 'Failure' : 'Unknown event'} on line ${buildAnchor.toString()}`}
        </div>
      </Popup>
    </Dropdown>
  )
}
