import Dropdown, {Anchor} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {resolveRelative} from '@jetbrains/teamcity-ui/dist/utils'
import * as React from 'react'

import {getBuild} from '../../../../selectors'
import {stringifyId} from '../../../../types'
import type {BuildId, NormalizedBuild} from '../../../../types'
import PopupMenu from '../../../common/Popup/PopupMenu'
import {downloadLogHint} from '../../Hints/HintItems/Hints.buildOverview'
import {useHint} from '../../Hints/Hints.hooks'

import styles from './DownloadBuildLog.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const directions = [
  PopupMenu.PopupProps.Directions.BOTTOM_LEFT,
  PopupMenu.PopupProps.Directions.TOP_LEFT,
]
type Props = {
  buildId: BuildId
  className?: string
  anchor?: React.ReactElement
  'data-test'?: string
}

function DownloadBuildLog({buildId, className, anchor}: Props) {
  const build: Partial<NormalizedBuild> = useAppSelector(state => getBuild(state, buildId)) ?? {}
  const canRender = build.state != null && build.state !== 'queued'
  const link = `/app/buildLog?buildId=${stringifyId(buildId)}&indent=true`
  useHint(canRender && downloadLogHint)
  const items = [
    {
      label: 'Full build log',
      href: resolveRelative(link),
    },
    {
      label: 'Zip file',
      href: resolveRelative(`${link}&compress=true`),
    },
    {
      label: 'Raw message file',
      href: resolveRelative(`/app/buildLog/raw?buildId=${stringifyId(buildId)}`),
    },
  ]
  const renderAnchor = () => (
    <Anchor className={styles.anchor}>
      <SvgIcon icon="download" className={styles.icon} />
      {'Download log'}
    </Anchor>
  )
  return canRender ? (
    <Dropdown
      anchor={anchor ?? renderAnchor()}
      hoverMode
      className={className}
      data-test={'download-buildlog-link'}
      data-hint-container-id={downloadLogHint.id}
    >
      <PopupMenu data={items} closeOnSelect directions={directions} />
    </Dropdown>
  ) : null
}

export default React.memo(DownloadBuildLog)
