import {branch, renderNothing} from 'recompose'

import compose from 'lodash/flowRight'
import {connect} from 'react-redux'

import type {State} from '../../../../reducers/types'
import {getBuild, getExtensionEndpoint} from '../../../../selectors'
import {getFullLogShowedFirstDate} from '../BuildLog.selectors'

import BuildLogTimeline from './BuildLogTimeline'
import type {OwnProps, StateProps, Props} from './BuildLogTimeline.types'

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const build = getBuild(state, props.buildId)
  const extensionEnabled = Boolean(getExtensionEndpoint(state, 'fetchBuildLogTimeline'))
  return {
    startDate: build?.startDate,
    extensionEnabled,
    showedFirstDate: getFullLogShowedFirstDate(state, props.logTarget),
    running: build?.state === 'running',
    queued: build?.state === 'queued',
  }
}

export default compose(
  connect(mapStateToProps),
  branch(({extensionEnabled}: Props) => !extensionEnabled, renderNothing),
)(BuildLogTimeline)
