import {withHandlers} from 'recompose'

import compose from 'lodash/flowRight'
import {connect} from 'react-redux'

import {fetchBuildLogMessages} from '../../../BuildLog.actions'
import {
  getKeyForBuildLogData,
  INITIAL_NEXT_MESSAGES_COUNT,
  INITIAL_PREVIOUS_MESSAGES_COUNT,
} from '../../../BuildLog.utils'

import TimelineStageButton from './TimelineStageButton'
import type {ActionProps, HandlersOwnProps} from './TimelineStageButton.types'

const actionCreators: ActionProps = {
  fetchMessages: fetchBuildLogMessages,
}
export default compose(
  connect(null, actionCreators),
  withHandlers({
    onClick:
      ({fetchMessages, buildId, stageKey, logTarget}: HandlersOwnProps) =>
      () => {
        fetchMessages({
          buildId,
          buildLogKey: getKeyForBuildLogData({
            type: 'full',
            target: logTarget,
            id: buildId,
          }),
          options: {
            count: [INITIAL_NEXT_MESSAGES_COUNT, INITIAL_PREVIOUS_MESSAGES_COUNT],
            stageKey,
          },
          invalidate: true,
          target: logTarget,
        })
      },
  }),
)(TimelineStageButton)
